function fnv1a(str, seed){
  var h=(0x811c9dc5 ^ (seed>>>0))>>>0;
  for(var i=0;i<str.length;i++){ h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193)>>>0; }
  return h>>>0;
}
function bloomHashes(item, m, k, seed){
  var h1=fnv1a(item, seed);
  var h2=fnv1a(item, (seed ^ 0x9e3779b9)>>>0) || 1;
  if(h2===0) h2=1;
  var out=[];
  for(var i=0;i<k;i++){ out.push((h1 + i*h2) % m); }
  return out;
}
function bloomCreate(m, k, seed){
  return { m:m, k:k, seed:(seed===undefined?0x9e3779b9:seed)>>>0, bits:new Array(m).fill(0) };
}
function bloomAdd(bf, item){
  var hs=bloomHashes(item, bf.m, bf.k, bf.seed);
  for(var i=0;i<hs.length;i++) bf.bits[hs[i]]=1;
  return bf;
}
function bloomHas(bf, item){
  var hs=bloomHashes(item, bf.m, bf.k, bf.seed);
  for(var i=0;i<hs.length;i++) if(!bf.bits[hs[i]]) return false;
  return true;
}
function bloomFalsePositiveRate(k, m, n){
  var x=Math.exp(-k*n/m);
  return Math.pow(1-x, k);
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { bloomCreate:bloomCreate, bloomAdd:bloomAdd, bloomHas:bloomHas,
    bloomFalsePositiveRate:bloomFalsePositiveRate, fnv1a:fnv1a };
}
if (typeof window !== 'undefined') {
  window.BloomForgePure = { bloomCreate:bloomCreate, bloomAdd:bloomAdd, bloomHas:bloomHas,
    bloomFalsePositiveRate:bloomFalsePositiveRate };
